{"rob": "robolang 1.3;

task put_boxes(robot r, object a, object b, location s1, location s2, location t, location c) {
    goal { object_at a t; object_at b c; }
    plan {
        move r to s1;
        grasp r a;
        move r to t;
        place r a at t;
        move r to s2;
        grasp r b;
        move r to c;
        place r b at c;
    }
}
